INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Beat Legend: Avicii', 'Soar through vocal melodies, sweep each fade and attack every beat in 15 of Avicii’s biggest hits, in this enthralling futuristic rhythm-action experience. From the developers of the acclaimed Avicii Invector, Beat Legend: AVICII brings the frenetic rhythm-action experience to mobile, and features mega-hits like Without You, Wake Me Up and Levels.' FROM games WHERE igdb_id = 175320 ON CONFLICT (game_id, language_code) DO NOTHING;
