INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Farm Builder', 'Farm Builder is strategy puzzle board game in which you have to construct farms, roads and surround windmills and water-towers in order to score points. The game is online multiplayer and in each room can play between 2 and 5 people together. The winner is the player who manages to score the most points. To make points you have to own a completed farm, road, windmill or water tower. This is done by placing farmers and tractors (pieces) which indicate that you own the property.' FROM games WHERE igdb_id = 147255 ON CONFLICT (game_id, language_code) DO NOTHING;
