INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Last Archmage Journey of Light', 'The legendary mage Merlin betrayed by his teammates in the holy war, fall from one of the legendary heroes to a rookie mage, and proceed the journey to the light with the help of new teammates. Along the way, you''ll have to collect various magic scrolls and items to use in the combat.' FROM games WHERE igdb_id = 168010 ON CONFLICT (game_id, language_code) DO NOTHING;
