INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Santa''s Xmas Adventure', 'Santa had an accident! He Lost his way, and all the Gifts. Help him get to his goal by sliding tiles to form a path. A classic puzzle game which is harder than it looks! 720 levels across three modes to master. Test your skills and join Santa''s adventure! Stone tiles can''t be moved. Aim to win with as few moves as possible. When you''re stuck, use a hint. Are you up for the challenge?' FROM games WHERE igdb_id = 138194 ON CONFLICT (game_id, language_code) DO NOTHING;
