INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cazzarion Adventureland', 'Cazzarion Adventureland is a sci-fi action-adventure platformer. The game has no overloaded controls - just jump and run like in the goods old days. Avoid the traps and jump on the enemies to remove them from the platform. In the levels you can find coins and treasures. Collect them by jumping on them.' FROM games WHERE igdb_id = 147594 ON CONFLICT (game_id, language_code) DO NOTHING;
