INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'City 13', 'City 13 is a dynamic 2D platformer. Combining the good old mechanics of classic games straight from the nineties and the modern directions of the hardcore platformer genre, City 13 is the quintessence of the old and new generations and will suit any platformer lover. Hardcore gameplay, varied levels, unique enemies and traps, brutal bosses, all this is for you in City 13.' FROM games WHERE igdb_id = 139589 ON CONFLICT (game_id, language_code) DO NOTHING;
