INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spider Solitaire', 'Spider Solitaire is one of the most popular solitaire games in the world! If you are a big fan of Spider Solitaire, Klondike solitaire, FreeCell Solitaire or other card games, you will love this spectacular and highly polished game! Change the game''s appearance to suit your own taste. Progress through the game to unlock unique card sets and backgrounds. Customize your Solitare to make it unique and exclusive. Stunning animations and gameplay designed for endless entertainment in the palm of your hand.' FROM games WHERE igdb_id = 83466 ON CONFLICT (game_id, language_code) DO NOTHING;
