INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'My Diggy Dog 2', 'The gameplay combines the genres of digger and platformer. During their adventures the player will explore dungeons full of challenging puzzles and find a variety of equipment, countless artifacts, and a large space for new discoveries. Features: -Journey to various locations -A large map to explore in any direction -Hidden collectible artifacts -Large dungeons full of traps and puzzles -Unique digging mechanics -Exciting bonus levels -A dynamic upgrade system -A touching story full of twists -Stunning graphics…' FROM games WHERE igdb_id = 139076 ON CONFLICT (game_id, language_code) DO NOTHING;
