INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('qube-qross', 147706, '2020-12-14', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co38tl.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arbkw.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Qube Qross', 'Qube Qross is a challenging and logical puzzle game, like Nonogram in 3D. The puzzles can be solved by the hints of numbers in the left and right sides of walls, players need to get where and how many cubes are located, by the intersection of numbers from left and right walls in the same height axis. And use your controller to place all the cubes in the right position to solve a puzzle. In the classic mode, we have 10 stages with different themes, there are 10 levels in each stage, all the puzzles you solve are aww-ing cute voxel models.' FROM games WHERE igdb_id = 147706 ON CONFLICT (game_id, language_code) DO NOTHING;
