INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Darkest Rogue: Slingshot RPG', 'Enjoy this turn-based roguelike RPG! Somewhere inside a dark prison, a burning pain causes the hero''s eyes to open. The only way to get free of their curse is to find the magic book called the "Necronomicon." Find the "Necronomicon" hidden within and banish the darkness of the dungeon to light the way forward. Face the cruel demigods and traps and survive till the end!' FROM games WHERE igdb_id = 174312 ON CONFLICT (game_id, language_code) DO NOTHING;
