INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'High Heels!', 'Get ready for the best high heels game ever! This shoe game is fun, this runway is epic, this shoe race is for baddies! The taller your heels are, the easier it will be to escape from the walls. A different obstacle awaits you at each parkour! There are rails on the roof where you have to spread your legs and slide, walls to jump, a stick to balance and a huge podium waiting for you at the end of the road.INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 241807 AND ge.slug = 'racing' ON CONFLICT DO NOTHING;
