INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('kana-quest', 126495, '2020-03-12', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1ynk.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arhh6.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kana Quest', 'Kana Quest is a puzzle game that teaches you how to read Japanese Hiragana. Each puzzle is a grid of different Hiragana that can be moved around. Adjacent Hiragana will connect to each other if the pronunciations share a common sound. So a Ka and a Na would connect as they both have an "a" sound. The player will rearrange the Hiragana to make one continuous connection between all the Hiragana in a level. When the player does this the puzzle will be complete. Some puzzles require figuring out the correct order of Hiragana. And others require the player to figure out the pronunciation of a Hiragana by looking at what connects with what.' FROM games WHERE igdb_id = 126495 ON CONFLICT (game_id, language_code) DO NOTHING;
