INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Megacraft Hentai Edition', 'Megacraft Hentai Edition will allow you to show your imagination! In this game, there is no pre-written plot, you have to create your own story. No one will tell you where to go and what to do, but you will probably understand everything yourself, because this amazing cubic world is familiar to all of us. Build, create and enjoy a cute character!' FROM games WHERE igdb_id = 144886 ON CONFLICT (game_id, language_code) DO NOTHING;
