INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mega Man Ram', 'A few months after Roboenza was cured, Sheep Man was back to his job working at a circuit board manufacturer. After routine checks, he found a mysterious computer program running on one of the terminals, and on contact with the monitor, a mysterious surge of energy transformed Sheep Man! Now, with his new powers, he wants to take over the world, and has recruited 6 Robot Masters to help! It''s up to Mega Man to stop his plans!' FROM games WHERE igdb_id = 209252 ON CONFLICT (game_id, language_code) DO NOTHING;
