INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Goop Loop', 'Goop Loop is a physics-based platformer with a simple mechanic that''s difficult to master: you jump and stick to a loop. Physics does the rest. Imagine a hamster ball, but with a giant booger, or something like that. There''s also commentary to egg you on. It''s a silly, fun, rage-inducing challenge.' FROM games WHERE igdb_id = 141073 ON CONFLICT (game_id, language_code) DO NOTHING;
