INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Long Gate', 'The Long Gate is a challenging and beautiful single-player, first-person, puzzle game. On a mission from the enigmatic creators of this place, you will explore ancient caverns filled with mysterious devices and traverse relaxing oases of nature while learning to solve the three primary types of puzzles that wind through them. Repair the ancient circuits and unravel the mystery of what happened to their creators.' FROM games WHERE igdb_id = 127215 ON CONFLICT (game_id, language_code) DO NOTHING;
