INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Aker Fern', 'The first three chapters tell the extraordinary story of Dan - self-proclaimed Casanova. As Dan, you will have the opportunity to experience exciting adventures with such celebrities as the incredibly strong Amazon Blanka, "lazy mother director Veronika" and the crazy reporter Tatiana. Today you are going to discover together what is behind a series of strange events in the haunted building located on the school grounds ... Will you go on this journey with our heroes?' FROM games WHERE igdb_id = 143726 ON CONFLICT (game_id, language_code) DO NOTHING;
