INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Infliction: Extended Cut', 'Wander through an interactive nightmare set within the confines of a once-happy household. Uncover the heartbreaking mystery hidden within messages, artwork, household objects, and other vestiges of domestic life all while struggling to survive encounters with an entity that relentlessly stands in the way of finding absolution. Hide under tables or beneath beds and harness light sources like camera flashes to stun the spirit and momentarily elude its pursuit.' FROM games WHERE igdb_id = 132969 ON CONFLICT (game_id, language_code) DO NOTHING;
