INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'THE ART: Metamorphosis', 'The Art is a puzzle game where you have to arrange the fragments of the picture in the correct sequence. You are going to see a lot of artwork in a variety of styles and genres of painting. By experimenting with the message that artists put into their work, you will be able to comprehend a little more in the art than can be seen at first glance by most of the people; you will be able to let a bit of art through yourself and finish the started artworks.INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 123492 AND ge.slug = 'indie' ON CONFLICT DO NOTHING;
