INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pinball Soccer World', 'A fast paced pinball game with soccer rules and realistic pinball physics that allow for real-world pinball techniques like post passes, ball cradling, nudging, and more. The game features an extensive and challenging career mode, hundreds of collectibles, multiple game-play modes, numerous ways to challenge your friends, and leaderboards where players collectively contribute to their national team''s rank in the world.' FROM games WHERE igdb_id = 354475 ON CONFLICT (game_id, language_code) DO NOTHING;
