INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tuneria', 'Tuneria is a music-focused RPG inspired by games such as Golden Sun, Ocarina of Time, Chrono Trigger, and To the Moon. Tuneria is a 2d RPG where you can use your keyboard to hold frets and pick your guitar strings. Use your guitar in battle by playing powerful Tunes, or use those same tunes in the environment to discover hidden secrets. Completely original soundtrack composed by Chaotrope.' FROM games WHERE igdb_id = 140025 ON CONFLICT (game_id, language_code) DO NOTHING;
