INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Snapto', 'SNAPto is a challenging Sokoban-Style puzzle exploration game centred around a single snapping mechanic. Players are given a series of dense and deceptively simple puzzles with increasing difficulty. Each puzzle is unique in introducing a principle of the game''s core mechanics and acts as a bridge to lead the Player to new places. The player is asked to discover the rules and history of this world, but is never certain of what is true.' FROM games WHERE igdb_id = 352945 ON CONFLICT (game_id, language_code) DO NOTHING;
