INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zombie Hills', 'Zombies are coming! Defeat all the zombies, build and conquer the tallest hill in the world! The main feature of Zombie Hills is based on the terrain elevation after the enemies are defeated. You will need to use strategies to shape it as needed and achieve game goals. Zombie Hills is an addicting action game based on one simple rule: every zombie is a brick to elevate you to the sky!' FROM games WHERE igdb_id = 139905 ON CONFLICT (game_id, language_code) DO NOTHING;
