INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tamiku', 'You are an alien from a distant galaxy who is totally obsessed with blow up balloons. Having popped every last balloon on your home planet, now you must venture to other worlds in search of more balloons to pop. Inspired by classic arcade games, Tamiku is an arcade game in which you have to burst all the balloons of a level without being killed. To do this you will face different dangers, jump, run and quickly inflate the red balloons!' FROM games WHERE igdb_id = 140952 ON CONFLICT (game_id, language_code) DO NOTHING;
