INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jungle Town: Birthday quest', 'A cognitive game for children from 2 to 5 years old, which teaches different life skills, contains tasks for attentiveness and fine motor skills. The plot is based on the birthday of the baby elephant, his friends prepare gifts with their own hands, and in the finale they go to a festive party.' FROM games WHERE igdb_id = 170498 ON CONFLICT (game_id, language_code) DO NOTHING;
