INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('soul-of-yokai', 229529, '2020-08-23', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5xag.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sckd6p.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Soul of Yokai', 'You are a young businesswoman who has recently gone through a break-up. You travel to Kyoto in hopes of mending your broken heart and maybe finding a new love. You didn''t, however, expect it to come in the form of a Yokai (Japanese demon). After a chance encounter, you are invited to the Yokai world, where you meet three attractive young men of varying Yokai races: Hayato a half Oni, Yukio of the Yukiotoko race, and Karasu of the Tengu. You are surprised to find out that they all want your hand in marriage! Not everything is peaches and cream, however, as you notice a darkness looming over the Yokai townspeople, and a growing dislike of human beings.
