INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('wordherd', 147269, '2020-03-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co59hp.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar98z.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'WordHerd', 'Work your way from simple to obscure and obtuse words in this brilliant, twisty, word finding puzzle game. Help Mia call the lost animals home before nightfall. Learn some modern, obscure and comic meanings as you try to beat your longest, rarest and highest scoring words through the ninety levels of word detective animal rescue. Mia will do her best to help you but when she''s out of words you''re on your own... Words can twist and turn across the board, any word you find can help Mia. Watch out for the new letter blocks and brain teaser levels with extra rules for really fussy animals. Use the +Control Pad and A Button or the touch screen and stylus to highlight words you find, new letters fall from the sky to make ever more interesting combinations. Knock letters out by tapping or attempting to use them three times in a row, but be careful, Mia will only let you do that three times on each level!' FROM games WHERE igdb_id = 147269 ON CONFLICT (game_id, language_code) DO NOTHING;
