INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fate/Empire of Dirt', 'Fate/Empire of Dirt is an adult fan game Visual Novel RPG based on the universe of Type-Moon. The game mixes elements from the Visual Novel genre, with the way the story is presented to the player; simulation elements, with a calendar system that gives the player the opportunity to spend time and bond with the heroines; and RPG elements, with dungeons and a combat system inspired by the mobile game Fate/Grand Order, in which the player can pick 3 different kind of attacks with different properties each as well as selecting skills to use during combat.' FROM games WHERE igdb_id = 232783 ON CONFLICT (game_id, language_code) DO NOTHING;
