INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('jaghund-armoured-organ-delivery-service', 329941, '2020-04-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9cc2.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scv7oq.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jaghund Armoured Organ Delivery Service', 'Since the MAW Lojackers, a group of low-tech anarchists lost control of their insect horde all of society has crumbled into a battle of survival. You have one mission, and one only; you must stay alive to deliver the heart. Travis, the CEO of Orbital Biotech Deliveries, requires a heart transplant and you are the last functional drone capable of completing such a request. The Lojackers will stop at nothing to capture your cargo. Use what power you can gather to charge up any of Fujisaki Corp’s bots you might find.' FROM games WHERE igdb_id = 329941 ON CONFLICT (game_id, language_code) DO NOTHING;
