INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Prisoner of War', 'Set in the thick of world war two, Lieutenant George Andrews has been captured and held prisoner by the Germans, due to high volumes in the prisoner camps the Lieutenant has been sent to the Jewish camps to face the horrors alone. In this top down prison escape, you will be faced with challenges such as sneaking passed guards, picking up letters which in turn give ideas to find tools in order to escape the prison.
