INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Concept Destruction', 'Concept Destruction is all about driving miniature cars made of cardboard, and crashing them into each other to earn points by destroying them! Pick from several different modes that suits your playstyle. Pick championship mode if you want to fight your way through mass production or choose survival mode to see how long you can survive a wave of deadly cardboard automobiles!' FROM games WHERE igdb_id = 123561 ON CONFLICT (game_id, language_code) DO NOTHING;
