INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Forking Hell', 'Forking Hell is a single player 3D casual arcade-simulation game where the player guides a forklift vehicle around a virtual warehouse and completes customer orders over the working days. The chaos of the Rumba-Bots combined with the semi-realistic physics helps give an arcade style to the simulation genre. Forking Hell is built with controller or keyboard/mouse input to support various play-styles and preferences.' FROM games WHERE igdb_id = 133906 ON CONFLICT (game_id, language_code) DO NOTHING;
