INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shuffs', 'No scarecrow can navigate the intricate, physics based puzzles laid out across Bowkin County without a cool, capable player behind the wheel. Could that be you? Do you have the resourcefulness to scour your environment for objects and projectiles to aid you in this journey? Do you have a keen eye to suss out the solution to these pesky little puzzles? Do you have the skills to take said objects and projectiles, juggle and hurl them through said puzzles, and pull out a stylish trick shot or two along the way?' FROM games WHERE igdb_id = 134253 ON CONFLICT (game_id, language_code) DO NOTHING;
