INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Election Year Knockout', 'Become President in this hilarious Punch-Out-inspired political sim where all laws have been replaced with boxing! Each opponent has unique tactics and special moves to test your skill and strategy on your way to the White House! Form your own third party and hit the campaign trail. Literally.' FROM games WHERE igdb_id = 130663 ON CONFLICT (game_id, language_code) DO NOTHING;
