INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'BiteVille', 'Society as we know has ceased to exist due to a deadly virus, the undead now roam the lands and you have managed to survive, so far... While running for your life you stumble upon a small city. Claim this city as your own, protect it with your life and maybe other survivors will find you.' FROM games WHERE igdb_id = 140322 ON CONFLICT (game_id, language_code) DO NOTHING;
