INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Black Desert Online: Prestige Edition', 'Black Desert is a revolutionary MMORPG that delivers intense, fast-paced combat, life activities, and an expansive open world. Made with Pearl Abyss’ proprietary game engine, Black Desert provides state-of-the-art graphics with spectacular sceneries, realistic environments, and sophisticated details. In addition to that, the insane level of customization allows you to edit everything from height, torso, face, skin texture, to micro-level details, making it possible to create your own unique characters for any of 19 classes currently available in the game.' FROM games WHERE igdb_id = 139914 ON CONFLICT (game_id, language_code) DO NOTHING;
