INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Geezer Gus: The Meteorite Motel', 'The Meteorite Motel is a surreal JRPG based upon the Geezer Gus franchise. Upon receiving news of an unidentified meteorite landing near the area, Gus makes his way to the crash site known as the Meteorite Motel. Among the loathsome and vile occupants of the motel lies a suspicious colony, who are interested in harnessing the meteorite''s power. The player must navigate through the unpredictable and dangerous motel with the help of formidable allies in order the reach the meteorite first.' FROM games WHERE igdb_id = 318356 ON CONFLICT (game_id, language_code) DO NOTHING;
