INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Squeen''s Adventure', 'After Squeen''s beloved spaceship suffers a oil leak, Squeen loses control and crash lands onto Earth. Now while that wouldn''t be so bad on its own, Squeen also realizes that his phone''s battery is low! Help Squeen in finding parts to repair his ship so he can get back to his home planet and charge his phone!' FROM games WHERE igdb_id = 212389 ON CONFLICT (game_id, language_code) DO NOTHING;
