INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Friendly Premonition', 'Friendly Premonition is a talking sim where you can meet every character from the original game and listen to them talk your ear off about a range of interests. Once they''ve run out of specific topics, they''ll eagerly share whatever thought enters their head. A select number of characters even have special mechanics for you after you''ve talked to them enough, so make sure you check back.' FROM games WHERE igdb_id = 242811 ON CONFLICT (game_id, language_code) DO NOTHING;
