INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ginkgo', 'Ginkgo is a single player 3D horror game set in a dreamlike space inspired by East Asian horror. Armed with a magic needle that can sew parts of the world together, solve puzzles and outsmart monsters as you explore a surreal world.' FROM games WHERE igdb_id = 144975 ON CONFLICT (game_id, language_code) DO NOTHING;
