INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kropki 8', 'Kropki 8 is an abstract strategy game, played by two or more people. The game is superficially similar to Go, in that the goal is to "capture" enemy dots by surrounding them with a continuous line of one''s own dots. Once an area containing enemy dots is surrounded, that area ceases to be playable.' FROM games WHERE igdb_id = 147739 ON CONFLICT (game_id, language_code) DO NOTHING;
