INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Experimental Turnabout', 'Phoenix, Maya, and Edgeworth awake in a courtroom that seems normal at first, but is in fact one located within a virtual reality created by an individual known only as the Game Master, who insists that this will be a ''history-making experiment''. Now the trio must play along with his scheme and complete the trial he has laid out while working together to figure out who the Game Master is, why he''s conducting this experiment, and just how they wound up in this situation at all.' FROM games WHERE igdb_id = 308421 ON CONFLICT (game_id, language_code) DO NOTHING;
