INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Retrowave Need For Speed Drift', 'Retrowave Need for Speed Drift (also known as Retrowave Drift) is an arcade speed game developed and published by ChangeMe for PC. A driving game that, despite its name, has nothing to do with the famous Electronic Arts series, in which we have to drive with vibrant, 80s-style neon colors, while listening to electronic synthesizer music, and overtake cars at full speed to get the best scores.' FROM games WHERE igdb_id = 359814 ON CONFLICT (game_id, language_code) DO NOTHING;
