INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('super-club-tennis', 147857, '2020-07-16', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5aue.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arbnn.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Club Tennis', 'Ignite the tennis court! unleash your sports talents in all-out tennis battles with family and friends. Whether you play solo or multi-player, intense rallies await! Join Tournament to win the Grand Slam trophy. Store up the energy to unleash unstoppable power shots and KO your opponents. Craft your own signatures styles and strategies to win matches. Pit your skills against friends and family in a multiplayer match. Accumulate experience points to level up and unlock new mini-games. Collect keys in mini-games to battle Aces from the galaxy! Only the best of the bests, can defeat the Aces and keep the trophies from across the universe! Attend Ace Academy to earn certificate engraved with your nickname. Take a snapshot to show-off with friends. Train and perfect your slice shot, drop shot, banana curve, top spins with tennis ball launcher. Admire all your war trophies and treasures troves from the gallery. Remember to collect daily gold handouts to help you with the games. A unique mega game, waiting for you to discover the gem packed hours of funs!' FROM games WHERE igdb_id = 147857 ON CONFLICT (game_id, language_code) DO NOTHING;
