INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sakura Stars', 'When hordes of Youkai threaten the world, the Tanukis send a messenger to choose human girls to receive magical powers to defend humanity. They are known as SAKURA STARS. This is a horizontal shmup made on Pico-8, a retro fantasy console with purposeful limitations to simulate an 8-bit era console.' FROM games WHERE igdb_id = 132662 ON CONFLICT (game_id, language_code) DO NOTHING;
