INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bounty Battle', 'Bounty Battle is the indie fighting game -- a new multiplayer 2D fighting game, where you can square off as your favorite indie hero against other indie heroes from games like Guacamelee!, Darkest Dungeon, Dead Cells, and Psychonauts 2 among other awesome indies. The game features more than 30 character, each with their own companion Minion and unique abilities. It’s Super Smash Bros. meets indie games where you battle across levels inspired from indie game worlds with up to 4 players' FROM games WHERE igdb_id = 107873 ON CONFLICT (game_id, language_code) DO NOTHING;
