INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('great-conqueror-rome', 146681, '2020-09-24', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co57pk.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arcf6.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Great Conqueror: Rome', 'A strategy experience with incredible detail and depth, you control great Commanders including Caesar, Pompey, Antony, Octavian, and Spartacus. Make major decisions on deployments, city improvements and more to emerge victorious! Take on the Campaign mode to relive history and lead an empire across Africa, Europe and Asia. Lead legions across historic wars, build cities, recruit soldiers, develop gear and naval fleets, and research new technologies – you have control. In Conquest mode you create history during Rome’s era; choose from many countries and forge a path to glory. Form alliances, declare war, and build your empire to be the most powerful in the world! For an extra challenge there is Expedition mode; take on 5 different scenarios in which you undertake a variety of battles that’ll truly test your leadership; can you make good use of limited resources and units? Great Conqueror: Rome brings unparalleled strategy gameplay, historical detail and content to Nintendo Switch; prepare to bring glory to Rome!' FROM games WHERE igdb_id = 146681 ON CONFLICT (game_id, language_code) DO NOTHING;
