INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nephila', 'For as long as memory serves, a tower reaching all the way to heaven has served as the center of human civilization, its upper floors shrouded in mystery. But recently, legions of monsters have been unleashed upon the world, sent by Aeus, the lord of Pandemonium. Now you must arm yourself, and find a way to reach him. Explore the world, battle monsters, find upgrades, and learn the ancient secrets.' FROM games WHERE igdb_id = 378670 ON CONFLICT (game_id, language_code) DO NOTHING;
