INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crate Punks: Dada is Dead', 'The new Crate Punks: Dada is Dead release is a ground-up remake of the titular 2016 crate-throwing battle game. A clever game of crate action chess, perfect for sharing a couch with your friends. Each arena is made of 100% crates, which means anything you can stand on can and will be used as a weapon.' FROM games WHERE igdb_id = 136098 ON CONFLICT (game_id, language_code) DO NOTHING;
