INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Torto: Cursed Divine', 'Torto cursed divine is a 2D adventure with basic climbing mechanics that allow you to explore an island to find challenges and beat them in the order you prefer. Every area you visit has a temple full of puzzles and enemies that will unlock access to a God''s location awaiting for you to battle.' FROM games WHERE igdb_id = 140842 ON CONFLICT (game_id, language_code) DO NOTHING;
