INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Verdant Village', 'Verdant Village is a fantasy life simulation game. Explore the massive Empyrean Vale. There are crops to tend, ore to mine, fish to catch, and secrets to discover. Meet the townsfolk and start a life. Live the way you want, build a thriving farm, or set your own goals, the decision is yours!' FROM games WHERE igdb_id = 134277 ON CONFLICT (game_id, language_code) DO NOTHING;
