INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('educational-games-for-kids', 147919, '2020-09-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3ps3.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arb87.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Educational Games for Kids', 'You are a parent and you are trying to relax a little by playing your favorite game. Your child keeps asking you to let them try it… But this game is not suitable for children (because it’s a little scary and not educational at all). Does this situation sound familiar? At last: a well thought-out, smart, polished, ‘console quality’ educational game pack is out for your kids. Suitable for boys and girls from ages 3 to 18. A pack of 21 different games with 51 variations that educate in various ways like: reflexes, logic, math, memory and knowledge. Keep track of your child''s progress with our statistics. All games have easy-to-learn controls with interesting and fun things to do. At last, a pack of games designed to educate and make your children smarter. The game runs natively in FHD when supported.' FROM games WHERE igdb_id = 147919 ON CONFLICT (game_id, language_code) DO NOTHING;
