INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dungeon of Rikka', 'Dungeon of Rikka is a turn based Rogue-like game with the goal to save your village from the impending doom of the beast that''s been left to rot in the deepest corner of the Dungeon. The beast will break his shackles and ascend the Dungeon, becoming stronger the longer you take to get to him.' FROM games WHERE igdb_id = 129337 ON CONFLICT (game_id, language_code) DO NOTHING;
