INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Drying Paint Simulator VR', 'After a long and cold journey, "the artist" has finally arrived at his deserted cabin in the woods. The perfect peaceful place to create his final masterpiece. The artist''s Magmum Opis. Drying Paint Simulator VR is the narrated exhilarating story of an artist (you) creating their last painting. A masterpiece.' FROM games WHERE igdb_id = 129003 ON CONFLICT (game_id, language_code) DO NOTHING;
