INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Motion', 'Motion is a fast-paced first-person physics shooter. Grab objects from a distance and repel them at enemies with force. You must survive against waves of enemies by using the weapons of the environment. Burn, electrocute, explode, and slice your enemies, and see how long you can last!' FROM games WHERE igdb_id = 130173 ON CONFLICT (game_id, language_code) DO NOTHING;
