INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dave.exe', 'Dave.EXE is a third-person low-poly stealth horror game loosely based off of the video game "Dead by Daylight", which the creator has a love-hate relationship with. You play as Dave Microwave, an everyman trying to live his life, until one day being pulled into warfare by the Berrys against Edgy Dave. You''ll travel through timelines and collect soda from five machines while avoiding whichever of Edgy Dave''s ranks is hunting you that round.' FROM games WHERE igdb_id = 276020 ON CONFLICT (game_id, language_code) DO NOTHING;
