INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Molly and the Gunmids', 'A shoot ''em up / adventure full of drawings and sounds. There''s one sound that''s really annoying at one point, and that is the best sound in the game. Some of the drawings look as if they were drawn by a 1 year old baby. You can even explore a solar system and read a tiny book while fighting a sun demon.' FROM games WHERE igdb_id = 185687 ON CONFLICT (game_id, language_code) DO NOTHING;
