INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Liar Trick: Psychological Crime Mystery', 'Are all your expressions "real"? The content of a person''s words can be both truthful or false. In this new psychological crime mystery game you will unveil "lies" through emotions! You can play Visual Novel Stories, Facial Expression Analysis Mode, Liar mode, and Deduction Mode.' FROM games WHERE igdb_id = 163961 ON CONFLICT (game_id, language_code) DO NOTHING;
